pairs=list(itertools.combinations('ABCDE',2));worlds=[]
for flags in itertools.product([0,1],repeat=10):
 edges={p for p,v in zip(pairs,flags) if v};neighbors={x:{y for y in 'ABCDE' if tuple(sorted((x,y))) in edges} for x in 'ABCDE'}
 if 'B' in neighbors['A'] or len(neighbors['A']&neighbors['B'])<3:continue
 if neighbors['A']&neighbors['D']:continue
 neutral=[p for p in pairs if p not in edges and len(neighbors[p[0]]&neighbors[p[1]])<=1]
 assert ('D','E') not in edges and len(neighbors['D']&neighbors['E'])==2 and ('A','D') in edges and not neutral
 worlds.append(dict(edges=sorted(edges),neutral=neutral))
assert len(worlds)==2
